<?php
declare(strict_types=1);

use DigiForge\Database\Tables;
use DigiForge\Listings\EtsyOperationRepository;

/** Local persistence acceptance with explicit synthetic reviewed scope; no execution grant. */
final class EtsyPersistedLifecycleAcceptanceTest extends WP_UnitTestCase {
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));}
 private function operation():array {
  global $wpdb;$now=current_time('mysql',true);$hash=hash('sha256',wp_generate_uuid4());
  self::assertSame(1,$wpdb->insert(Tables::listings(),['product_version_id'=>1,'environment'=>'sandbox','shop_reference'=>'digital','title'=>'Synthetic ledger fixture','state'=>'APPROVED','approved_by'=>get_current_user_id(),'approved_at'=>$now,'created_at'=>$now,'updated_at'=>$now]));$listing=(int)$wpdb->insert_id;
  self::assertSame(1,$wpdb->insert(Tables::etsy_draft_packages(),['listing_id'=>$listing,'package_version'=>'v1','canonical_payload'=>'{}','payload_hash'=>$hash,'readiness'=>'{}','readiness_hash'=>$hash,'approved_by'=>get_current_user_id(),'approved_at'=>$now,'created_at'=>$now]));$package=(int)$wpdb->insert_id;
  self::assertSame(1,$wpdb->insert(Tables::etsy_intents(),['listing_id'=>$listing,'draft_package_id'=>$package,'environment'=>'sandbox','intent_type'=>'PREPARE_DRAFT','state'=>'APPROVED_INTENT','created_at'=>$now,'updated_at'=>$now]));$intent=(int)$wpdb->insert_id;
  $operation=(new EtsyOperationRepository())->createFromPayload(['shop_reference'=>'digital','intent_id'=>$intent,'draft_package_id'=>$package,'operation_type'=>'CREATE_DRAFT','idempotency_key'=>'native-'.wp_generate_uuid4(),'authorization_hash'=>$hash,'evidence_hash'=>$hash],['title'=>'Synthetic fixture']);self::assertNotWPError($operation);return $operation;
 }
 public function testPayloadFingerprintAndTerminalExternalIdentityArePersistedAndCannotBeRebound():void {
  $operation=$this->operation();$repo=new EtsyOperationRepository();self::assertSame(DigiForge\Listings\EtsyRequestFingerprint::fromPayload(['title'=>'Synthetic fixture']),$operation['request_fingerprint']);
  $conflict=$repo->createFromPayload($operation,['title'=>'Different fixture']);self::assertWPError($conflict);self::assertSame('digiforge_etsy_operation_request_fingerprint_conflict',$conflict->get_error_code());
  $outcomes=new DigiForge\Listings\EtsyAdapterOutcomePersistenceService($repo);self::assertWPError($outcomes->record((int)$operation['id'],['state'=>'CONFIRMED_SUCCESS','external_reference'=>'8801']));self::assertNotWPError($repo->transition((int)$operation['id'],'SENT'));self::assertWPError($outcomes->record((int)$operation['id'],['state'=>'CONFIRMED_SUCCESS','external_reference'=>'']));
  self::assertNotWPError($outcomes->record((int)$operation['id'],['state'=>'CONFIRMED_SUCCESS','external_reference'=>'8801']));self::assertWPError($repo->transition((int)$operation['id'],'CONFIRMED_FAILURE'));self::assertWPError($repo->transition((int)$operation['id'],'CONFIRMED_SUCCESS','8802'));$stored=$repo->find((int)$operation['id']);self::assertSame('CONFIRMED_SUCCESS',$stored['state']);self::assertSame('8801',$stored['external_reference']);
 }
 public function testConfirmedFailureRetryRequiresFreshPersistedKeyAndAuthorizationWhileUnknownIsNotRetryable():void {
  $operation=$this->operation();$repo=new EtsyOperationRepository();$retry=new DigiForge\Listings\EtsyRetryOperationService($repo);$new=hash('sha256','new authorization');$evidence=hash('sha256','new evidence');
  self::assertWPError($retry->create((int)$operation['id'],'fresh',$new,$evidence,[]));self::assertNotWPError($repo->transition((int)$operation['id'],'SENT'));self::assertNotWPError($repo->transition((int)$operation['id'],'UNKNOWN'));self::assertWPError($retry->create((int)$operation['id'],'fresh',$new,$evidence,[]));self::assertWPError($repo->transition((int)$operation['id'],'CONFIRMED_FAILURE'));self::assertNotWPError($repo->transition((int)$operation['id'],'RECONCILIATION'));self::assertNotWPError($repo->transition((int)$operation['id'],'RECONCILED'));self::assertNotWPError($repo->transition((int)$operation['id'],'CONFIRMED_FAILURE'));
  self::assertWPError($retry->create((int)$operation['id'],$operation['idempotency_key'],$new,$evidence,[]));self::assertWPError($retry->create((int)$operation['id'],'fresh',$operation['authorization_hash'],$evidence,[]));$created=$retry->create((int)$operation['id'],'fresh',$new,$evidence,['title'=>'retry fixture']);self::assertNotWPError($created);self::assertNotSame((int)$operation['id'],(int)$created['operation']['id']);self::assertSame('NOT_SENT',$created['operation']['state']);self::assertSame($new,$created['operation']['authorization_hash']);self::assertWPError($retry->create((int)$operation['id'],'fresh',hash('sha256','third auth'),$evidence,[]));self::assertSame('CONFIRMED_FAILURE',$repo->find((int)$operation['id'])['state']);self::assertTrue(DigiForge\Core\Settings::safety_locked());
 }
 public function testExternalAttemptIdentityMustBeDurableBeforeSentAndWriteFailureCannotNormalizeSuccess():void {
  $operation=$this->operation();$id=(int)$operation['id'];$repo=new EtsyOperationRepository();$sent=new DigiForge\Listings\EtsySentTransitionService($repo);$evidence=['state'=>'ETSY_EXTERNAL_ATTEMPT_EVIDENCED','operation_id'=>$id,'attempt_id'=>'offline-attempt-'.$id,'attempted_at'=>gmdate('c'),'sent_transition_eligible'=>true,'sent_transition_performed'=>false,'external_execution_performed'=>true];
  self::assertNotWPError($sent->record($evidence));global $wpdb;$context=$wpdb->get_var($wpdb->prepare('SELECT context FROM '.Tables::audit_log().' WHERE event_type=%s AND object_type=%s AND object_id=%s ORDER BY id DESC LIMIT 1','etsy_external_attempt_recorded','etsy_operation',(string)$id));self::assertIsString($context,'External attempt identity must survive beyond transient service return values.');$stored=json_decode($context,true);self::assertSame($evidence['attempt_id'],$stored['attempt_id']);self::assertSame($evidence['attempted_at'],$stored['attempted_at']);self::assertSame('SENT',$repo->find($id)['state']);
  $other=$this->operation();$evidence['operation_id']=(int)$other['id'];$evidence['attempt_id']='offline-attempt-'.$other['id'];$table=Tables::audit_log();$fail=static fn(string $sql):string=>str_starts_with($sql,'INSERT INTO `'.$table.'`')&&str_contains($sql,'etsy_external_attempt_recorded')?'INSERT INTO no_such_etsy_attempt_table (id) VALUES (1)':$sql;
  add_filter('query',$fail);try{self::assertWPError($sent->record($evidence));}finally{remove_filter('query',$fail);}self::assertSame('NOT_SENT',$repo->find((int)$other['id'])['state']);
 }
 public function testConsumedNonceCannotBecomePublishOrBeReusedAndPrecallRecoveryCreatesFreshBinding():void {
  $operation=$this->operation();$repo=new EtsyOperationRepository();$nonce='offline_'.str_replace('-','',wp_generate_uuid4());$approval=['state'=>'HUMAN_APPROVED','decision'=>'APPROVE','publishing_enabled'=>false,'order_execution_enabled'=>false,'evidence_hash'=>$operation['evidence_hash']];
  $auth=DigiForge\POD\ExecutionAuthorization::issue($approval,'ETSY_DRAFT_CREATE',get_current_user_id(),$nonce);self::assertNotWPError($auth);global $wpdb;self::assertSame(1,$wpdb->update($wpdb->prefix.'digiforge_etsy_operations',['authorization_hash'=>$auth['authorization_hash']],['id'=>$operation['id']]));
  self::assertWPError(DigiForge\POD\ControlledExecutionGate::authorize($auth,'ETSY_PUBLISH_LISTING',$operation['evidence_hash'],get_current_user_id(),time()));self::assertTrue(DigiForge\POD\ExecutionNonceLedger::unused($nonce));
  $permit=DigiForge\POD\ControlledExecutionGate::authorize($auth,'ETSY_DRAFT_CREATE',$operation['evidence_hash'],get_current_user_id(),time());self::assertNotWPError($permit);self::assertTrue($permit['nonce_consumed']);self::assertFalse(DigiForge\POD\ExecutionNonceLedger::unused($nonce));self::assertWPError(DigiForge\POD\ControlledExecutionGate::authorize($auth,'ETSY_DRAFT_CREATE',$operation['evidence_hash'],get_current_user_id(),time()));
  $prepared=['state'=>'ETSY_OPERATION_PREPARED','operation_id'=>(int)$operation['id'],'permit'=>$permit,'adapter_invoked'=>false,'external_execution_performed'=>false];$replacement=new DigiForge\Listings\EtsyPreCallReplacementService($repo);$newHash=hash('sha256','fresh-precall-'.wp_rand());$newEvidence=hash('sha256','fresh-evidence-'.wp_rand());
  self::assertWPError($replacement->create((int)$operation['id'],$prepared,'replacement',$auth['authorization_hash'],$newEvidence,[]));self::assertWPError($replacement->create((int)$operation['id'],$prepared,$operation['idempotency_key'],$newHash,$newEvidence,[]));self::assertWPError($replacement->create((int)$operation['id'],$prepared,'replacement',$newHash,$operation['evidence_hash'],[]));
  $fresh=$replacement->create((int)$operation['id'],$prepared,'replacement',$newHash,$newEvidence,['title'=>'fresh payload']);self::assertNotWPError($fresh);self::assertTrue($fresh['new_nonce_required']);self::assertFalse($fresh['reuse_prior_authorization']);self::assertNotSame((int)$operation['id'],(int)$fresh['operation']['id']);self::assertSame('NOT_SENT',$fresh['operation']['state']);self::assertSame('NOT_SENT',$repo->find((int)$operation['id'])['state']);self::assertFalse(DigiForge\POD\ExecutionNonceLedger::unused($nonce));self::assertTrue(DigiForge\Core\Settings::safety_locked());
 }
 public function testDurableAttemptRejectsRelativeUnzonedInvalidCalendarAndControlCharacterIdentity():void {
  $repo=new EtsyOperationRepository();foreach(['tomorrow','2026-10-12T12:00:00','2026-02-30T12:00:00+00:00','2026-10-12T12:00:00+25:00']as $at){$op=$this->operation();self::assertWPError($repo->recordExternalAttempt(['operation_id'=>$op['id'],'attempt_id'=>'bounded-id','attempted_at'=>$at,'adapter_invoked'=>true,'external_request_attempted'=>true]));self::assertSame('NOT_SENT',$repo->find((int)$op['id'])['state']);}
  foreach(["id\nforged","id\x00forged",'../unsafe-id']as $id){$op=$this->operation();self::assertWPError($repo->recordExternalAttempt(['operation_id'=>$op['id'],'attempt_id'=>$id,'attempted_at'=>gmdate('c'),'adapter_invoked'=>true,'external_request_attempted'=>true]));}
 }
}
